import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1794112334000}'),t={name:"ja/guide/faq.md"};function o(s,a,h,c,n,d){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><h2 id="一般的な質問" tabindex="-1">一般的な質問 <a class="header-anchor" href="#一般的な質問" aria-label="Permalink to &quot;一般的な質問&quot;">​</a></h2><h3 id="nicasa-とは何ですか" tabindex="-1">Nicasa とは何ですか？ <a class="header-anchor" href="#nicasa-とは何ですか" aria-label="Permalink to &quot;Nicasa とは何ですか？&quot;">​</a></h3><p>Nicasa は macOS 専用に設計された、モダンなデスクトップ画像ビューア兼スクリーンショットツールです。クリーンで反応の良いインターフェースで画像コレクションを素早く直感的に閲覧でき、強力な AI 編集機能も備えています。</p><h3 id="nicasa-は無料ですか" tabindex="-1">Nicasa は無料ですか？ <a class="header-anchor" href="#nicasa-は無料ですか" aria-label="Permalink to &quot;Nicasa は無料ですか？&quot;">​</a></h3><p>Chrome 拡張機能は完全無料でダウンロード・利用できます。macOS アプリはすべての機能を利用するために $4.99 の買い切り購入が必要です。</p><h3 id="対応しているオペレーティングシステムは" tabindex="-1">対応しているオペレーティングシステムは？ <a class="header-anchor" href="#対応しているオペレーティングシステムは" aria-label="Permalink to &quot;対応しているオペレーティングシステムは？&quot;">​</a></h3><p>Nicasa は現在 macOS 10.13 以降専用です。Windows 版と Linux 版は現時点では提供していません。</p><h3 id="nicasa-はどうやって更新しますか" tabindex="-1">Nicasa はどうやって更新しますか？ <a class="header-anchor" href="#nicasa-はどうやって更新しますか" aria-label="Permalink to &quot;Nicasa はどうやって更新しますか？&quot;">​</a></h3><p>更新は Mac App Store を通じて行われます。新しいバージョンが利用可能になると通知され、App Store アプリから直接更新できます。</p><h2 id="使い方の質問" tabindex="-1">使い方の質問 <a class="header-anchor" href="#使い方の質問" aria-label="Permalink to &quot;使い方の質問&quot;">​</a></h2><h3 id="nicasa-でスクリーンショットを撮るには" tabindex="-1">Nicasa でスクリーンショットを撮るには？ <a class="header-anchor" href="#nicasa-でスクリーンショットを撮るには" aria-label="Permalink to &quot;Nicasa でスクリーンショットを撮るには？&quot;">​</a></h3><ol><li>Nicasa を起動します</li><li>ツールバーのスクリーンショットボタンをクリックするか、<code>Cmd+S</code> を押します</li><li>キャプチャしたい領域を選択します</li><li>スクリーンショットが Nicasa で開き、すぐに編集できます</li></ol><h3 id="ウェブ画像を扱えますか" tabindex="-1">ウェブ画像を扱えますか？ <a class="header-anchor" href="#ウェブ画像を扱えますか" aria-label="Permalink to &quot;ウェブ画像を扱えますか？&quot;">​</a></h3><p>はい！無料の Nicasa Chrome 拡張機能をインストールすると：</p><ul><li>任意のウェブサイトのすべての画像を 1 か所で閲覧できます</li><li>画像をその場で抽出して閲覧できます</li><li>Nicasa で直接画像を開き、より快適に閲覧できます</li></ul><h3 id="どのような-ai-編集機能がありますか" tabindex="-1">どのような AI 編集機能がありますか？ <a class="header-anchor" href="#どのような-ai-編集機能がありますか" aria-label="Permalink to &quot;どのような AI 編集機能がありますか？&quot;">​</a></h3><p>Nicasa には強力な AI ツールが組み込まれています：</p><ul><li><strong>自動補正</strong>：画質を自動的に向上</li><li><strong>スマート切り抜き</strong>：インテリジェントな切り抜き提案</li><li><strong>インペイント</strong>：不要なオブジェクトをインテリジェントに削除</li><li><strong>色補正</strong>：AI による色調整</li><li><strong>ノイズ除去</strong>：ノイズや粒状感を除去</li></ul><h3 id="透明オーバーレイモードはどう動作しますか" tabindex="-1">透明オーバーレイモードはどう動作しますか？ <a class="header-anchor" href="#透明オーバーレイモードはどう動作しますか" aria-label="Permalink to &quot;透明オーバーレイモードはどう動作しますか？&quot;">​</a></h3><p>デザイナーやアーティストに最適です：</p><ul><li>画像を調整可能な透明度で他のすべてのウィンドウの前面に固定</li><li>トレース、参照資料との照合、UI 比較に利用</li><li>すべてのアプリケーションにわたって位置を保持</li></ul><h2 id="技術的な質問" tabindex="-1">技術的な質問 <a class="header-anchor" href="#技術的な質問" aria-label="Permalink to &quot;技術的な質問&quot;">​</a></h2><h3 id="なぜ画面収録の権限が必要なのですか" tabindex="-1">なぜ画面収録の権限が必要なのですか？ <a class="header-anchor" href="#なぜ画面収録の権限が必要なのですか" aria-label="Permalink to &quot;なぜ画面収録の権限が必要なのですか？&quot;">​</a></h3><p>スクリーンショット機能には画面収録の権限が必要です。これにより、スクリーンショットツールを使用したときに Nicasa が画面をキャプチャできます。</p><h3 id="オフラインで-nicasa-を使えますか" tabindex="-1">オフラインで Nicasa を使えますか？ <a class="header-anchor" href="#オフラインで-nicasa-を使えますか" aria-label="Permalink to &quot;オフラインで Nicasa を使えますか？&quot;">​</a></h3><p>はい。macOS アプリはローカル画像ファイルに対して完全にオフラインで動作します。Chrome 拡張機能によるウェブ画像の抽出にはインターネット接続が必要です。</p><h3 id="対応している-macos-のバージョンは" tabindex="-1">対応している macOS のバージョンは？ <a class="header-anchor" href="#対応している-macos-のバージョンは" aria-label="Permalink to &quot;対応している macOS のバージョンは？&quot;">​</a></h3><p>Nicasa は macOS 10.13 以降に対応しています。Apple シリコンに最適化され、M シリーズチップ上でネイティブに動作します。</p><h3 id="chrome-拡張機能にはどの権限が必要ですか" tabindex="-1">Chrome 拡張機能にはどの権限が必要ですか？ <a class="header-anchor" href="#chrome-拡張機能にはどの権限が必要ですか" aria-label="Permalink to &quot;Chrome 拡張機能にはどの権限が必要ですか？&quot;">​</a></h3><p>この拡張機能は画像 URL を抽出する目的に限り、ページコンテンツへのアクセスを要求します。閲覧履歴の読み取りや保存は行いません。</p><h3 id="データはどこかにアップロードされますか" tabindex="-1">データはどこかにアップロードされますか？ <a class="header-anchor" href="#データはどこかにアップロードされますか" aria-label="Permalink to &quot;データはどこかにアップロードされますか？&quot;">​</a></h3><p>いいえ。すべての処理は端末上で行われます。Nicasa が画像を収集・送信・保存することはありません。</p><h3 id="設定をバックアップするには" tabindex="-1">設定をバックアップするには？ <a class="header-anchor" href="#設定をバックアップするには" aria-label="Permalink to &quot;設定をバックアップするには？&quot;">​</a></h3><p>設定はローカルに保存されます。バックアップ方法：</p><ol><li>Nicasa &gt; 環境設定 に移動します</li><li>対応していれば設定を書き出します</li><li>またはアプリの環境設定フォルダを手動でバックアップします</li></ol><p>設定はアプリのデータフォルダに保存されています。このフォルダをコピーしてバックアップしてください。</p><h3 id="ポータブル版はありますか" tabindex="-1">ポータブル版はありますか？ <a class="header-anchor" href="#ポータブル版はありますか" aria-label="Permalink to &quot;ポータブル版はありますか？&quot;">​</a></h3><p>Windows 版にはポータブル版があります。当社のウェブサイトからダウンロードできます。</p><h2 id="開発に関する質問" tabindex="-1">開発に関する質問 <a class="header-anchor" href="#開発に関する質問" aria-label="Permalink to &quot;開発に関する質問&quot;">​</a></h2><h3 id="nicasa-に貢献できますか" tabindex="-1">Nicasa に貢献できますか？ <a class="header-anchor" href="#nicasa-に貢献できますか" aria-label="Permalink to &quot;Nicasa に貢献できますか？&quot;">​</a></h3><p><a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">GitHub リポジトリ</a>にアクセスして、コードの提供、問題の報告、機能の提案ができます。</p><h3 id="ソースから-nicasa-をビルドするには" tabindex="-1">ソースから Nicasa をビルドするには？ <a class="header-anchor" href="#ソースから-nicasa-をビルドするには" aria-label="Permalink to &quot;ソースから Nicasa をビルドするには？&quot;">​</a></h3><p>ビルド手順については GitHub の開発者向けドキュメントをご覧ください。</p><h3 id="nicasa-はどの技術を使っていますか" tabindex="-1">Nicasa はどの技術を使っていますか？ <a class="header-anchor" href="#nicasa-はどの技術を使っていますか" aria-label="Permalink to &quot;Nicasa はどの技術を使っていますか？&quot;">​</a></h3><p>Nicasa は Electron によるデスクトップラッパーと Vue.js によるインターフェースを含む、モダンなウェブ技術で構築されています。</p><h2 id="プライバシーに関する質問" tabindex="-1">プライバシーに関する質問 <a class="header-anchor" href="#プライバシーに関する質問" aria-label="Permalink to &quot;プライバシーに関する質問&quot;">​</a></h2><h3 id="nicasa-はデータを収集しますか" tabindex="-1">Nicasa はデータを収集しますか？ <a class="header-anchor" href="#nicasa-はデータを収集しますか" aria-label="Permalink to &quot;Nicasa はデータを収集しますか？&quot;">​</a></h3><p>いいえ。Nicasa は個人データを収集・送信しません。すべての画像処理は端末上で行われます。</p><h3 id="私の画像は安全ですか" tabindex="-1">私の画像は安全ですか？ <a class="header-anchor" href="#私の画像は安全ですか" aria-label="Permalink to &quot;私の画像は安全ですか？&quot;">​</a></h3><p>はい。Nicasa は明示的に開いた画像にのみアクセスします。ファイルをアップロードしたり共有したりすることはありません。</p><h3 id="nicasa-にはどの権限が必要ですか" tabindex="-1">Nicasa にはどの権限が必要ですか？ <a class="header-anchor" href="#nicasa-にはどの権限が必要ですか" aria-label="Permalink to &quot;Nicasa にはどの権限が必要ですか？&quot;">​</a></h3><p>Nicasa は画像の読み取りと設定の保存のためにファイルシステムへのアクセスが必要です。動作にインターネット接続は必要ありません。</p><h2 id="まだ質問がありますか" tabindex="-1">まだ質問がありますか？ <a class="header-anchor" href="#まだ質問がありますか" aria-label="Permalink to &quot;まだ質問がありますか？&quot;">​</a></h2><p>ここで答えが見つからない場合は：</p><ol><li><a href="/ja/">ドキュメント全体</a>をご覧ください</li><li><a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub issues</a>を検索してください</li><li>必要に応じて新しい issue を作成してください</li></ol><p>喜んでお手伝いします！</p>',57)])])}const b=i(t,[["render",o]]);export{p as __pageData,b as default};
